### Connection Pooling

```typescript
// v3/@claude-flow/plugins/src/bridges/ruvector-postgres/connection-manager.ts

import { Pool, PoolClient, PoolConfig } from 'pg';

export interface ConnectionManagerConfig {
  host: string;
  port: number;
  database: string;
  user: string;
  password: string;
  ssl?: boolean | object;
  poolSize: number;
  idleTimeout: number;
  connectionTimeout: number;
}

export class ConnectionManager {
  private pool: Pool | null = null;
  private config: ConnectionManagerConfig;
  private healthCheckInterval: NodeJS.Timer | null = null;
  private stats = {
    totalConnections: 0,
    activeConnections: 0,
    idleConnections: 0,
    waitingClients: 0,
    totalQueries: 0,
    failedQueries: 0,
    avgQueryTime: 0,
  };

  constructor(config: ConnectionManagerConfig) {
    this.config = config;
  }

  async initialize(): Promise<void> {
    const poolConfig: PoolConfig = {
      host: this.config.host,
      port: this.config.port,
      database: this.config.database,
      user: this.config.user,
      password: this.config.password,
      ssl: this.config.ssl,
      max: this.config.poolSize,
      idleTimeoutMillis: this.config.idleTimeout,
      connectionTimeoutMillis: this.config.connectionTimeout,
    };

    this.pool = new Pool(poolConfig);

    // Set up event listeners
    this.pool.on('connect', () => {
      this.stats.totalConnections++;
      this.stats.activeConnections++;
    });

    this.pool.on('remove', () => {
      this.stats.activeConnections--;
    });

    this.pool.on('error', (err) => {
      this.stats.failedQueries++;
      console.error('PostgreSQL pool error:', err);
    });

    // Verify connection
    const client = await this.pool.connect();
    try {
      await client.query('SELECT 1');
    } finally {
      client.release();
    }

    // Start health check
    this.healthCheckInterval = setInterval(
      () => this.performHealthCheck(),
      30000
    );
  }

  async shutdown(): Promise<void> {
    if (this.healthCheckInterval) {
      clearInterval(this.healthCheckInterval);
    }
    if (this.pool) {
      await this.pool.end();
      this.pool = null;
    }
  }

  async query<T = unknown>(
    sql: string,
    params?: unknown[]
  ): Promise<{ rows: T[]; rowCount: number }> {
    if (!this.pool) {
      throw new Error('Connection pool not initialized');
    }

    const start = Date.now();
    this.stats.totalQueries++;

    try {
      const result = await this.pool.query(sql, params);
      const duration = Date.now() - start;
      this.updateAvgQueryTime(duration);
      return { rows: result.rows, rowCount: result.rowCount ?? 0 };
    } catch (error) {
      this.stats.failedQueries++;
      throw error;
    }
  }

  async withTransaction<T>(
    fn: (client: PoolClient) => Promise<T>
  ): Promise<T> {
    if (!this.pool) {
      throw new Error('Connection pool not initialized');
    }

    const client = await this.pool.connect();
    try {
      await client.query('BEGIN');
      const result = await fn(client);
      await client.query('COMMIT');
      return result;
    } catch (error) {
      await client.query('ROLLBACK');
      throw error;
    } finally {
      client.release();
    }
  }

  async batch<T>(
    operations: Array<{ sql: string; params?: unknown[] }>
  ): Promise<T[]> {
    return this.withTransaction(async (client) => {
      const results: T[] = [];
      for (const op of operations) {
        const result = await client.query(op.sql, op.params);
        results.push(result.rows as T);
      }
      return results;
    });
  }

  getStats(): typeof this.stats {
    return { ...this.stats };
  }

  private async performHealthCheck(): Promise<void> {
    try {
      await this.query('SELECT 1');
    } catch (error) {
      console.error('Health check failed:', error);
    }
  }

  private updateAvgQueryTime(duration: number): void {
    const n = this.stats.totalQueries;
    this.stats.avgQueryTime =
      (this.stats.avgQueryTime * (n - 1) + duration) / n;
  }
}
```

