describe('Vector Search Benchmarks', () => {
  let adapter: AgentDBAdapter;
  const VECTOR_DIM = 1536; // OpenAI embedding dimension
  const DATASET_SIZE = 100000;

  beforeAll(async () => {
    adapter = await AgentDBAdapter.create({
      indexType: 'hnsw',
      dimension: VECTOR_DIM
    });

