    const agent = new Agent({
      name: 'test-agent',
      modules: { memory }
    });

    const task = { id: '1', type: 'test' };
    const result = await agent.execute(task);

    expect(result).toBeDefined();
    expect(result.success).toBe(true);

    // Verify event was emitted
